import{_ as t,o as n,c as s,a2 as l}from"./chunks/framework.DpXDHk3d.js";const c=JSON.parse('{"title":"1.1 安全生产法律法规体系","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/01-chapter-1-an-quan-sheng-chan-fa-l-fa-gui/1-1-an-quan-sheng-chan-fa-l-fa-gui-ti-xi.md","filePath":"electrician/low-voltage-electrician/01-chapter-1-an-quan-sheng-chan-fa-l-fa-gui/1-1-an-quan-sheng-chan-fa-l-fa-gui-ti-xi.md","lastUpdated":1793095197000}'),e={name:"electrician/low-voltage-electrician/01-chapter-1-an-quan-sheng-chan-fa-l-fa-gui/1-1-an-quan-sheng-chan-fa-l-fa-gui-ti-xi.md"};function i(r,a,o,d,h,p){return n(),s("div",null,[...a[0]||(a[0]=[l(`<h1 id="_1-1-安全生产法律法规体系" tabindex="-1">1.1 安全生产法律法规体系 <a class="header-anchor" href="#_1-1-安全生产法律法规体系" aria-label="Permalink to &quot;1.1 安全生产法律法规体系&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>电工师傅日常作业,背后靠一整套法律法规在&quot;撑腰&quot;和保护。本节目的是让你知道:<strong>有哪些法规在管电工这行</strong>、它们之间的层次关系,以及哪几部法跟你考证、干活关系最大。</p><h2 id="一、法律的层次-金字塔结构" tabindex="-1">一、法律的层次:金字塔结构 <a class="header-anchor" href="#一、法律的层次-金字塔结构" aria-label="Permalink to &quot;一、法律的层次:金字塔结构&quot;">​</a></h2><p>我国的法律体系像一座金字塔,越往上效力越高,越往下规定越具体:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────┐</span></span>
<span class="line"><span>│          宪法(根本大法)           │  ← 最高效力</span></span>
<span class="line"><span>├──────────────────────────────┤</span></span>
<span class="line"><span>│          法律(全国人大制定)        │  ← 如《安全生产法》</span></span>
<span class="line"><span>├──────────────────────────────┤</span></span>
<span class="line"><span>│     行政法规(国务院制定)          │  ← 如《安全生产许可证条例》</span></span>
<span class="line"><span>├──────────────────────────────┤</span></span>
<span class="line"><span>│     地方性法规(地方人大制定)       │  ← 各省条例</span></span>
<span class="line"><span>├──────────────────────────────┤</span></span>
<span class="line"><span>│     部门规章(部委制定)            │  ← 如安监总局令第30号</span></span>
<span class="line"><span>├──────────────────────────────┤</span></span>
<span class="line"><span>│   国家标准 / 行业标准 / 企业标准   │  ← 技术规范,如 GB 3805</span></span>
<span class="line"><span>└──────────────────────────────┘</span></span></code></pre></div><p><strong>通俗理解</strong>:宪法管大方向,法律定规矩,规章和标准给具体做法。如果下层文件的内容和上层冲突,以下层文件作废——&quot;下位法服从上位法&quot;。</p><h2 id="二、和低压电工关系最大的几部法规" tabindex="-1">二、和低压电工关系最大的几部法规 <a class="header-anchor" href="#二、和低压电工关系最大的几部法规" aria-label="Permalink to &quot;二、和低压电工关系最大的几部法规&quot;">​</a></h2><h3 id="_1-《中华人民共和国安全生产法》-核心大法" tabindex="-1">1.《中华人民共和国安全生产法》(核心大法) <a class="header-anchor" href="#_1-《中华人民共和国安全生产法》-核心大法" aria-label="Permalink to &quot;1.《中华人民共和国安全生产法》(核心大法)&quot;">​</a></h3><ul><li>最新修正:2021 年修正,<strong>2021 年 9 月 1 日</strong>施行。</li><li>安全生产方针:<strong>&quot;安全第一、预防为主、综合治理&quot;</strong>——这句话几乎是必考题。</li><li>明确规定:<strong>特种作业人员必须持证上岗</strong>(未经专门培训、未取得资格不得上岗)。</li><li>生产经营单位<strong>主要负责人</strong>是本单位安全生产<strong>第一责任人</strong>。</li></ul><h3 id="_2-《特种作业人员安全技术培训考核管理规定》" tabindex="-1">2.《特种作业人员安全技术培训考核管理规定》 <a class="header-anchor" href="#_2-《特种作业人员安全技术培训考核管理规定》" aria-label="Permalink to &quot;2.《特种作业人员安全技术培训考核管理规定》&quot;">​</a></h3><ul><li>由原国家安全生产监督管理总局以 <strong>30 号令</strong>发布,是&quot;怎么考电工证&quot;的直接依据。</li><li>规定了特种作业的范围、培训、考核、发证、复审、证书管理等全流程(详见 1.2 节)。</li></ul><h3 id="_3-《电业安全工作规程》与《用电安全导则》" tabindex="-1">3.《电业安全工作规程》与《用电安全导则》 <a class="header-anchor" href="#_3-《电业安全工作规程》与《用电安全导则》" aria-label="Permalink to &quot;3.《电业安全工作规程》与《用电安全导则》&quot;">​</a></h3><ul><li><strong>《电力安全工作规程》(发电厂和变电站电气部分)</strong>:规定了电气作业的组织措施、技术措施、操作规范,是电工作业的&quot;操作手册&quot;。</li><li><strong>GB/T 13869《用电安全导则》</strong>:从用电安全角度给出总要求,如安全用电的基本原则、用电设备的防护要求。</li></ul><h3 id="_4-常用电气安全标准-速记" tabindex="-1">4. 常用电气安全标准(速记) <a class="header-anchor" href="#_4-常用电气安全标准-速记" aria-label="Permalink to &quot;4. 常用电气安全标准(速记)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>标准代号</th><th>名称</th><th>核心内容</th></tr></thead><tbody><tr><td>GB 3805-2008</td><td>《安全电压》</td><td>安全电压额定值等级:42、36、24、12、6 V</td></tr><tr><td>GB/T 13869</td><td>《用电安全导则》</td><td>用电安全基本原则与要求</td></tr><tr><td>GB 26860</td><td>《电力安全工作规程 发电厂和变电站电气部分》</td><td>电气作业安全规定</td></tr><tr><td>GB/T 3805 相关</td><td>《电业安全工作规程》配套</td><td>停电、验电、挂地线等操作要求</td></tr></tbody></table><blockquote><p>💡 <strong>理解提示</strong>:标准分&quot;强制标准(GB)&quot;和&quot;推荐标准(GB/T)&quot;。<strong>GB 是必须执行的</strong>,GB/T 是推荐执行的——判断题常考这一点。</p></blockquote><h2 id="三、法律法规体系速记表" tabindex="-1">三、法律法规体系速记表 <a class="header-anchor" href="#三、法律法规体系速记表" aria-label="Permalink to &quot;三、法律法规体系速记表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>例子</th><th>跟你有什么关系</th></tr></thead><tbody><tr><td>法律</td><td>《安全生产法》</td><td>定下&quot;持证上岗&quot;的总规矩</td></tr><tr><td>行政法规</td><td>国务院相关条例</td><td>安全生产责任制等</td></tr><tr><td>部门规章</td><td>安监总局 30 号令</td><td>考证、复审的具体流程</td></tr><tr><td>标准</td><td>GB 3805、GB/T 13869</td><td>安全电压等具体技术数值</td></tr></tbody></table><h2 id="四、考点提示" tabindex="-1">四、考点提示 <a class="header-anchor" href="#四、考点提示" aria-label="Permalink to &quot;四、考点提示&quot;">​</a></h2><ul><li>✅ <strong>必背</strong>:《安全生产法》方针 = 安全第一、预防为主、综合治理。</li><li>✅ <strong>必背</strong>:特种作业人员必须<strong>持证上岗</strong>。</li><li>✅ 判断题常考:GB(强制) vs GB/T(推荐)。</li><li>⚠️ 易混点:《安全生产法》2021 年修正,<strong>2021 年 9 月 1 日</strong>起施行,别记成其他日期。</li></ul><h2 id="五、本节小结" tabindex="-1">五、本节小结 <a class="header-anchor" href="#五、本节小结" aria-label="Permalink to &quot;五、本节小结&quot;">​</a></h2><ul><li>我国法规分层次,下位法服从上位法。</li><li>电工考证与作业主要依据《安全生产法》+ 30 号令 + 电气安全标准。</li><li>记住安全生产&quot;三字方针&quot;:<strong>安全第一、预防为主、综合治理</strong>。</li></ul><h2 id="六、自测练习" tabindex="-1">六、自测练习 <a class="header-anchor" href="#六、自测练习" aria-label="Permalink to &quot;六、自测练习&quot;">​</a></h2><ol><li>(判断)我国安全生产的基本方针是&quot;安全第一、预防为主、综合治理&quot;。( )</li><li>(单选)低压电工作业属于()作业,作业人员必须持证上岗。 A. 普通作业　B. 特种作业　C. 危险作业　D. 特殊作业</li><li>(判断)《安全生产法》最新修正版自 2021 年 9 月 1 日起施行。( )</li><li>(单选)GB 3805 规定的安全电压额定值等级中,不包括下列哪一档? A. 36V　B. 24V　C. 50V　D. 12V</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。这正是安全生产方针的完整表述。</li><li><strong>B</strong>。低压电工作业属于特种作业,必须经专门培训考核取得特种作业操作证才能上岗。</li><li><strong>√</strong>。2021 年修正版自 2021 年 9 月 1 日起施行。</li><li><strong>C</strong>。安全电压额定值等级为 42、36、24、12、6 V,<strong>没有 50V</strong>。</li></ol></details>`,26)])])}const g=t(e,[["render",i]]);export{c as __pageData,g as default};
